function setEnvValues(content, values, comment) {
  let result = content;
  const appended = [];
  for (const [name2, value] of Object.entries(values)) {
    const line = `${name2}=${quoteEnvValue(value)}`;
    const pattern = new RegExp(`^[ \\t]*(?:export[ \\t]+)?${name2}[ \\t]*=.*$`, "gm");
    let found = false;
    result = result.replace(pattern, () => {
      found = true;
      return line;
    });
    if (!found) {
      appended.push(line);
    }
  }
  if (appended.length === 0) {
    return result;
  }
  const block = [...comment ? [`# ${comment}`] : [], ...appended].join("\n");
  const base = result.trimEnd();
  return base.length === 0 ? `${block}
` : `${base}
${comment ? "\n" : ""}${block}
`;
}
